// SPDX-License-Identifier: BUSL-1.1
pragma solidity =0.8.20;

import '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';
import '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraFactory.sol';
import '../interfaces/plugins/ISecurityRegistry.sol';

contract SecurityRegistry is ISecurityRegistry {
  using EnumerableSet for EnumerableSet.AddressSet;
  address public immutable override algebraFactory;
  bytes32 public constant override GUARD = keccak256('GUARD');

  Status public override globalStatus;
  bool public override isPoolStatusOverrided;
  EnumerableSet.AddressSet private overriddenPools;

  mapping(address => Status) public poolStatus;

  constructor(address _algebraFactory) {
    algebraFactory = _algebraFactory;
  }

  function setPoolsStatus(address[] memory pools, Status[] memory newStatuses) external override {
    for (uint i = 0; i < pools.length; i++) {
      _hasAccess(newStatuses[i]);
      poolStatus[pools[i]] = newStatuses[i];

      if (newStatuses[i] == Status.ENABLED) {
        overriddenPools.remove(pools[i]);
      } else {
        overriddenPools.add(pools[i]);
      }
      emit PoolStatus(pools[i], newStatuses[i]);
    }

    if (overriddenPools.length() > 0) {
      isPoolStatusOverrided = true;
    } else {
      isPoolStatusOverrided = false;
    }
  }

  function setGlobalStatus(Status newStatus) external override {
    _hasAccess(newStatus);
    globalStatus = newStatus;
    emit GlobalStatus(newStatus);
  }

  function getPoolStatus(address pool) external view override returns (Status) {
    Status _globalStatus = globalStatus;
    bool _isPoolStatusOverrided = isPoolStatusOverrided;
    if (_isPoolStatusOverrided) {
      if (_globalStatus == Status.ENABLED) {
        return poolStatus[pool];
      } else {
        return _globalStatus;
      }
    } else {
      return _globalStatus;
    }
  }

  function _hasAccess(Status newStatus) internal view {
    if (newStatus == Status.ENABLED || newStatus == Status.BURN_ONLY) {
      require(msg.sender == IAlgebraFactory(algebraFactory).owner(), 'Only owner');
    } else {
      require(IAlgebraFactory(algebraFactory).hasRoleOrOwner(GUARD, msg.sender), 'Only guard');
    }
  }
}

contracts/plugins/SlidingFeePlugin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.20;

import {IAlgebraFactory} from '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraFactory.sol';
import {IAlgebraPool} from '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraPool.sol';
import {Timestamp} from '@cryptoalgebra/integral-core/contracts/base/common/Timestamp.sol';
import {TickMath} from '@cryptoalgebra/integral-core/contracts/libraries/TickMath.sol';
import {FullMath} from '@cryptoalgebra/integral-core/contracts/libraries/FullMath.sol';

import {ISlidingFeePlugin} from '../interfaces/plugins/ISlidingFeePlugin.sol';
import {AlgebraBasePlugin} from '../base/AlgebraBasePlugin.sol';

abstract contract SlidingFeePlugin is AlgebraBasePlugin, ISlidingFeePlugin {
  struct FeeFactors {
    uint128 zeroToOneFeeFactor;
    uint128 oneToZeroFeeFactor;
  }

  int16 internal constant FACTOR_DENOMINATOR = 1000;
  uint64 internal constant FEE_FACTOR_SHIFT = 96;

  FeeFactors public s_feeFactors;

  uint16 public s_priceChangeFactor = 1000;
  uint16 public s_baseFee = 3000;

  constructor(uint16 _baseFee) {
    FeeFactors memory feeFactors = FeeFactors(uint128(1 << FEE_FACTOR_SHIFT), uint128(1 << FEE_FACTOR_SHIFT));

    s_feeFactors = feeFactors;
    s_baseFee = _baseFee;
  }

  function _getFeeAndUpdateFactors(bool zeroToOne, int24 currenTick, int24 lastTick) internal returns (uint16) {
    FeeFactors memory currentFeeFactors;

    uint16 priceChangeFactor = s_priceChangeFactor;
    uint16 baseFee = s_baseFee;

    if (currenTick != lastTick) {
      currentFeeFactors = _calculateFeeFactors(currenTick, lastTick, priceChangeFactor);

      s_feeFactors = currentFeeFactors;
    } else {
      currentFeeFactors = s_feeFactors;
    }

    uint256 adjustedFee = zeroToOne
      ? (uint256(baseFee) * currentFeeFactors.zeroToOneFeeFactor) >> FEE_FACTOR_SHIFT
      : (uint256(baseFee) * currentFeeFactors.oneToZeroFeeFactor) >> FEE_FACTOR_SHIFT;

    if (adjustedFee > type(uint16).max) {
      adjustedFee = type(uint16).max;
    } else if (adjustedFee == 0) {
      adjustedFee = 1;
    }
    return uint16(adjustedFee);
  }

  function setPriceChangeFactor(uint16 newPriceChangeFactor) external override {
    _authorize();

    s_priceChangeFactor = newPriceChangeFactor;

    emit PriceChangeFactor(newPriceChangeFactor);
  }

  function setBaseFee(uint16 newBaseFee) external override {
    _authorize();

    s_baseFee = newBaseFee;
    emit BaseFee(newBaseFee);
  }

  function _calculateFeeFactors(int24 currentTick, int24 lastTick, uint16 priceChangeFactor) internal view returns (FeeFactors memory feeFactors) {
    int256 tickDelta = int256(currentTick) - int256(lastTick);
    if (tickDelta > TickMath.MAX_TICK) {
      tickDelta = TickMath.MAX_TICK;
    } else if (tickDelta < TickMath.MIN_TICK) {
      tickDelta = TickMath.MIN_TICK;
    }
    uint256 sqrtPriceDelta = uint256(TickMath.getSqrtRatioAtTick(int24(tickDelta)));

    // price change is positive after oneToZero prevalence
    int256 priceChangeRatio = int256(FullMath.mulDiv(sqrtPriceDelta, sqrtPriceDelta, 2 ** 96)) - int256(1 << FEE_FACTOR_SHIFT); // (currentPrice - lastPrice) / lastPrice
    int256 feeFactorImpact = (priceChangeRatio * int256(uint256(priceChangeFactor))) / FACTOR_DENOMINATOR;

    feeFactors = s_feeFactors;

    // if there were zeroToOne prevalence in the last price change,
    // in result price has increased
    // we need to decrease zeroToOneFeeFactor
    // and vice versa
    int256 newZeroToOneFeeFactor = int128(feeFactors.zeroToOneFeeFactor) - feeFactorImpact;

    if (0 < newZeroToOneFeeFactor && newZeroToOneFeeFactor < (int128(2) << FEE_FACTOR_SHIFT)) {
      feeFactors = FeeFactors(uint128(int128(newZeroToOneFeeFactor)), uint128(int128(feeFactors.oneToZeroFeeFactor) + int128(feeFactorImpact)));
    } else if (newZeroToOneFeeFactor <= 0) {
      // In this case price has decreased that much so newZeroToOneFeeFactor is less than 0
      // So we set it to the minimal value == 0
      // It means that there were too much oneToZero prevalence and we want to decrease it
      // Basically price change is -100%
      feeFactors = FeeFactors(0, uint128(2 << FEE_FACTOR_SHIFT));
    } else {
      // In this case priceChange is big enough that newZeroToOneFeeFactor is greater than 2
      // So we set it to the maximum value
      // It means that there were too much zeroToOne prevalence and we want to decrease it
      feeFactors = FeeFactors(uint128(2 << FEE_FACTOR_SHIFT), 0);
    }
  }
}

contracts/plugins/VolatilityOraclePlugin.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity =0.8.20;

import '@cryptoalgebra/integral-core/contracts/libraries/Plugins.sol';

import '../interfaces/IBasePlugin.sol';
import '../interfaces/IBasePluginV1Factory.sol';
import '../interfaces/plugins/IVolatilityOracle.sol';

import '../libraries/VolatilityOracle.sol';
import '../base/AlgebraBasePlugin.sol';

/// @title Algebra Integral 1.2.2 VolatilityOraclePlugin plugin
/// @notice This contract stores timepoints and calculates adaptive fee and statistical averages
abstract contract VolatilityOraclePlugin is AlgebraBasePlugin, IVolatilityOracle {
  using Plugins for uint8;

  uint256 internal constant UINT16_MODULO = 65536;
  using VolatilityOracle for VolatilityOracle.Timepoint[UINT16_MODULO];

  uint8 private constant defaultPluginConfig = uint8(Plugins.AFTER_INIT_FLAG | Plugins.BEFORE_SWAP_FLAG);

  /// @inheritdoc IVolatilityOracle
  VolatilityOracle.Timepoint[UINT16_MODULO] public override timepoints;

  /// @inheritdoc IVolatilityOracle
  uint16 public override timepointIndex;

  /// @inheritdoc IVolatilityOracle
  uint32 public override lastTimepointTimestamp;

  /// @inheritdoc IVolatilityOracle
  bool public override isInitialized;

  /// @inheritdoc IVolatilityOracle
  function initialize() external override {
    require(!isInitialized, 'Already initialized');
    require(_getPluginInPool() == address(this), 'Plugin not attached');
    (uint160 price, int24 tick, , ) = _getPoolState();
    require(price != 0, 'Pool is not initialized');
    _initialize_TWAP(tick);
  }

  function _initialize_TWAP(int24 tick) internal {
    uint32 time = _blockTimestamp();
    timepoints.initialize(time, tick);
    lastTimepointTimestamp = time;
    isInitialized = true;

    _enablePluginFlags(defaultPluginConfig);
  }
  // ###### Volatility and TWAP oracle ######

  /// @inheritdoc IVolatilityOracle
  function getSingleTimepoint(uint32 secondsAgo) external view override returns (int56 tickCumulative, uint88 volatilityCumulative) {
    // `volatilityCumulative` values for timestamps after the last timepoint _should not_ be compared: they may differ due to interpolation errors
    (, int24 tick, , ) = _getPoolState();
    uint16 lastTimepointIndex = timepointIndex;
    uint16 oldestIndex = timepoints.getOldestIndex(lastTimepointIndex);
    VolatilityOracle.Timepoint memory result = timepoints.getSingleTimepoint(_blockTimestamp(), secondsAgo, tick, lastTimepointIndex, oldestIndex);
    (tickCumulative, volatilityCumulative) = (result.tickCumulative, result.volatilityCumulative);
  }

  /// @inheritdoc IVolatilityOracle
  function getTimepoints(
    uint32[] memory secondsAgos
  ) external view override returns (int56[] memory tickCumulatives, uint88[] memory volatilityCumulatives) {
    // `volatilityCumulative` values for timestamps after the last timepoint _should not_ be compared: they may differ due to interpolation errors
    (, int24 tick, , ) = _getPoolState();
    return timepoints.getTimepoints(_blockTimestamp(), secondsAgos, tick, timepointIndex);
  }

  /// @inheritdoc IVolatilityOracle
  function prepayTimepointsStorageSlots(uint16 startIndex, uint16 amount) external override {
    require(!timepoints[startIndex].initialized); // if not initialized, then all subsequent ones too
    require(amount > 0 && type(uint16).max - startIndex >= amount);

    unchecked {
      for (uint256 i = startIndex; i < startIndex + amount; ++i) {
        timepoints[i].blockTimestamp = 1; // will be overwritten
      }
    }
  }

  function _writeTimepoint() internal {
    // single SLOAD
    uint16 _lastIndex = timepointIndex;
    uint32 _lastTimepointTimestamp = lastTimepointTimestamp;

    bool _isInitialized = isInitialized;
    require(_isInitialized, 'Not initialized');

    uint32 currentTimestamp = _blockTimestamp();
    if (_lastTimepointTimestamp == currentTimestamp) return;

    (, int24 tick, , ) = _getPoolState();
    (uint16 newLastIndex, ) = timepoints.write(_lastIndex, currentTimestamp, tick);

    timepointIndex = newLastIndex;
    lastTimepointTimestamp = currentTimestamp;
  }

  function _getAverageVolatilityLast() internal view returns (uint88 volatilityAverage) {
    uint32 currentTimestamp = _blockTimestamp();
    (, int24 tick, , ) = _getPoolState();

    uint16 lastTimepointIndex = timepointIndex;
    uint16 oldestIndex = timepoints.getOldestIndex(lastTimepointIndex);

    volatilityAverage = timepoints.getAverageVolatility(currentTimestamp, tick, lastTimepointIndex, oldestIndex);
  }

  function _getLastTick() internal view returns (int24 lastTick) {
    VolatilityOracle.Timepoint memory lastTimepoint = timepoints[timepointIndex];
    return lastTimepoint.tick;
  }
}

